[
  {
    "id": "c001",
    "name": "Insurer designation",
    "text": "This insurance is provided by the Company designated by 2 \"X\" in the box below: Zurich American Insurance Company"
  },
  {
    "id": "c002",
    "name": "Claims-made-and-reported policy",
    "text": "THIS IS A CLAIMS MADE AND REPORTED POLICY."
  },
  {
    "id": "c003",
    "name": "Claim reporting condition",
    "text": "“CLAIMS” MUST FIRST BE MADE AND REPORTED IN WRITING TO THE COMPANY DURING THE “CERTIFICATE PERIOD\" OR ANY APPLICABLE EXTENDED REPORTING PERIOD OF THIS POLICY,"
  },
  {
    "id": "c004",
    "name": "Defense costs outside limits",
    "text": "\"DEFENSE COSTS\" ARE PROVIDED IN ADDITION TO THE LIMITS OF LIABILITY,"
  },
  {
    "id": "c005",
    "name": "Item 1. Named Certificate Holder",
    "text": "lrem 1. \"Named Certificate Holder\" and Address: Jonathan D. Rosen 3805 Crestwood Pkwy, #175 Duluth GA 30096"
  },
  {
    "id": "c006",
    "name": "Item 2. Additional Insured",
    "text": "Protective Life Insurance Company and Empire General and the Registered Representatives of ProEquities, tac,"
  },
  {
    "id": "c007",
    "name": "Item 3. Producer and Mailing Address",
    "text": "Item 3, Producer and Mailing Address: | Kenneth P. Smith c/o a Insurance Specialties Services, Inc., 2370 York Read, Suite D4, Jamison, PA 18929"
  },
  {
    "id": "c008",
    "name": "Item 4. Each Claim Limit of Liability",
    "text": "Item 4. Limits of Liability: g $2,060,000,09 Each “Claim\"/Each “Named Certificate Holder\""
  },
  {
    "id": "c009",
    "name": "Item 4. Aggregate Limit of Liability",
    "text": "$2,000,000.00 Ageregate/Each \"Named Certificate Holder\""
  },
  {
    "id": "c010",
    "name": "Item 5. Certificate Period",
    "text": "2/45/2007 To 12:01 A.M. on 2/AS/2808 ltern 5. \"Certificate Period”: From {2:01 A.M. on Local time at the address shown in Item I of the \"Certificate of Insurance\""
  },
  {
    "id": "c011",
    "name": "Item 6. Protective and ProEquities Deductible",
    "text": "$500 each claim for covered claims involving products of Protective Life and ProEquities, Inc."
  },
  {
    "id": "c012",
    "name": "Item 6. Other Products Deductible",
    "text": "ftem 6, Deductible: $2,500 each claim for covered claims involving all other covered products"
  },
  {
    "id": "c013",
    "name": "Item 7. Premium",
    "text": "Item 7. Premium: Refer to Master Policy"
  },
  {
    "id": "c014",
    "name": "Item 8. Endorsements Effective at Inception",
    "text": "Item 8. Endorsements Effective at Inception: Refer to Master Policy"
  },
  {
    "id": "c015",
    "name": "Issuance under Master Policy",
    "text": "THIS \"CERTIFICATE OF INSURANCE” IS ISSUED IN ACCORDANCE WITH THE \"MASTER POLICY\" TO THE INSURANCE PROFESSIONALS PROTECTION GROUP, INC.."
  },
  {
    "id": "c016",
    "name": "Acceptance of statements and representations",
    "text": "BY ACCEPTANCE OF THIS POLICY THE “NAMED CERTFICATE HOLDER\" AGREES THAT THE STATEMENTS IN THE \"CERTIFICATE OF INSURANCE” AND THE APPLICATION AND ANY ATTACHMENTS HERETO ARE THE \"NAMED CERTIFICATE HOLDER'S” AGREEMENTS AND REPRESENTATIONS"
  },
  {
    "id": "c017",
    "name": "Entire agreement",
    "text": "AND THIS POLICY EMBODIES ALL AGREEMENTS EXISTING BETWEEN THE “NAMED CERTIFICATE HOLDER\" AND THE COMPANY GR ANY OF ITS REPRESENTATIVES RELATING TO THIS"
  }
]

